import { atom, read, update } from 'claude-code'
import type { EngineInterface as Engine, Register } from 'claude-code'

import type { Handoff } from '../types'

// The prompt cache lapses after 60 idle minutes. One read at 50 refreshes it;
// at 100 it is still warm from that read, so the handoff costs a cache read too.
export const PING_AFTER_MS = 50 * 60 * 1000
export const HANDOFF_AFTER_MS = 50 * 60 * 1000

const NEXT_MARKER = '===NEXT SESSION PROMPT==='

const PING_PROMPT = 'Keep-alive check. Reply with the single word: ok'

const HANDOFF_PROMPT = `Write a handoff document summarising this conversation so a fresh agent with none of this context can continue the work.

- Open with the goal, where things stand, and the exact next step.
- List decisions made and why, open questions, and anything tried that failed.
- Reference files, branches, PRs, issues, specs and commits by path or URL instead of copying their content.
- Include a "Suggested skills" section naming the skills the next agent should call the Skill tool for.
- Redact secrets, API keys, passwords and personal information.

Reply with the Markdown document, no preamble. Then, on a line of its own, write ${NEXT_MARKER} followed by the opening prompt for the next session: two to four sentences in the user's voice, addressed to the next agent, naming the concrete next step and what done looks like for it, plus any constraint the agent must not miss. It is pasted after a line telling the agent to read the doc, so do not repeat the doc or mention reading it.`

const FALLBACK_NEXT = 'Continue the work from where it leaves off.'

// Splits the fork's reply into the doc and the tailored opening prompt.
export function splitReply(reply: string) {
  const at = reply.lastIndexOf(NEXT_MARKER)
  if (at === -1) return { doc: reply.trim(), next: FALLBACK_NEXT }
  const next = reply.slice(at + NEXT_MARKER.length).trim()
  return { doc: reply.slice(0, at).trim(), next: next || FALLBACK_NEXT }
}

type Timer = { cancel: () => void }

let timer: Timer | undefined

// A plugin's system row is stored at level "info", which the transcript hides
// outside ctrl+o, so the handoff also sits above the prompt until the next turn.
const pending = atom({ plugin: 'cache-keeper', key: 'handoff' } as const, null)

function stop($: Engine) {
  timer?.cancel()
  timer = undefined
  $.ui.status(undefined)
}

async function dismiss($: Engine) {
  await update($, pending, () => null)
}

async function at($: Engine, ms: number) {
  return new Date((await $.clock.now()) + ms).toTimeString().slice(0, 5)
}

async function handoff($: Engine) {
  timer = undefined
  $.ui.status('cache-keeper: writing handoff…')
  const reply = await $.model.fork({ prompt: HANDOFF_PROMPT })
  if (!reply.isAnswered) {
    $.ui.status(undefined)
    $.ui.log(`cache-keeper: handoff not written (${reply.reason})`)
    return
  }

  const tmp = ((await $.env.get('TMPDIR')) ?? '/tmp').replace(/\/$/, '')
  const stamp = new Date(await $.clock.now()).toISOString().slice(0, 16).replace(/[:T]/g, '-')
  const path = `${tmp}/handoff-${(await $.session.id()).slice(0, 8)}-${stamp}.md`
  const { doc, next } = splitReply(reply.text)
  await $.fs.write(path, doc + '\n')

  const resume = `Read the handoff doc at ${path}. ${next}`
  const copied = await $.ui.copy({ text: resume }).catch(() => ({ isCopied: false }))
  await $.session.append({
    message: {
      type: 'system',
      content: [
        {
          type: 'text',
          text: [
            'cache-keeper: this conversation has been idle 100 minutes and its cache lapses in about 10.',
            `Handoff written to ${path}`,
            `To continue, /clear (or open a new window) and paste${copied.isCopied ? ' (already on your clipboard)' : ''}:`,
            '',
            resume,
          ].join('\n'),
        },
      ],
    },
  })
  const ready: Handoff = { path, resume }
  await update($, pending, () => ready)
  $.ui.status(undefined)
  $.ui.toast(`cache-keeper: handoff ready${copied.isCopied ? ', continue prompt copied' : ''}`)
}

async function ping($: Engine) {
  const reply = await $.model.fork({ prompt: PING_PROMPT })
  if (!reply.isAnswered) {
    timer = undefined
    $.ui.status(undefined)
    if (reply.reason !== 'nothing-to-fork') $.ui.log(`cache-keeper: warm ping failed (${reply.reason})`)
    return
  }
  const read = reply.usage.cache_read_input_tokens ?? 0
  $.ui.log(`cache-keeper: warm ping read ${Math.round(read / 1000)}k cached tokens`, { to: 'debug' })
  timer = $.clock.after(HANDOFF_AFTER_MS, () => void handoff($))
  $.ui.status(`cache-keeper: handoff at ${await at($, HANDOFF_AFTER_MS)}`)
}

async function arm($: Engine) {
  stop($)
  timer = $.clock.after(PING_AFTER_MS, () => void ping($))
  $.ui.status(`cache-keeper: warm ping at ${await at($, PING_AFTER_MS)}`)
}

export const register: Register = on => {
  on('turn.start', async ($, e, next) => {
    stop($)
    await dismiss($)
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    await arm($)
    return done
  })

  on('session.end', async ($, e, next) => {
    stop($)
    await dismiss($)
    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const ready = await read($, pending)
    if (e.props.hasSurvey || ready === null) return next(e)

    const { Box, Button, Text } = $.ui.resolve(e)
    return (
      <Box flexDirection="column">
        <Text>cache-keeper: idle 100 minutes, handoff written to {ready.path}</Text>
        <Text dimColor>/clear, then paste: {ready.resume}</Text>
        <Box>
          <Button key="copy" label="Copy prompt" onPress={() => $.ui.copy({ text: ready.resume }).then(() => undefined, () => undefined)} />
          <Button key="dismiss" label="Dismiss" onPress={() => dismiss($)} />
        </Box>
      </Box>
    )
  })
}

